const sourcePair = (category) => {
  if (category === "Pregnancy" || category === "Postpartum") return [NHS_PREGNANCY, HSE_PREGNANCY];
  if (category === "Contraception") return [NHS_CONTRACEPTION, HSE_SEXUAL_HEALTH];
  if (category === "Sexual health") return [NHS_AZ, HSE_SEXUAL_HEALTH];
  return [NHS_AZ, HSE_WOMENS_HEALTH];
};

const split = (value) => value.split("|");
const humanise = (value) => value.replaceAll("-", " ");

function createArticle([id, title, category, summary, symptomText, assessmentText, treatmentText, urgent]) {
  const symptoms = split(symptomText);
  const diagnosis = split(assessmentText);
  const treatments = split(treatmentText);

  return {
    id,
    slug: id,
    title,
    category,
    readTime: 8,
    summary,
    quickFacts: [summary, diagnosis[0], treatments[0]],
    symptoms,
    causes: [`The mechanism behind ${title.toLowerCase()} varies with life stage, medicines, pregnancy, infection and underlying pelvic or whole-body health.`],
    riskFactors: [`Relevant factors are assessed from the symptom pattern, medical and pregnancy history, medicines, procedures and family history rather than assumed from one feature.`],
    diagnosis,
    treatments,
    selfCare: [
      `Record ${symptoms.slice(0, 4).map(humanise).join(", ")} with timing, severity and effect on normal activities.`,
      "Follow the linked NHS or HSE safety-net advice and review medicines with a pharmacist or clinician when pregnant, breastfeeding or managing another condition.",
    ],
    whenToSeeGP: [
      `${humanise(symptoms[0])} is persistent, recurrent, worsening or different from your usual pattern.`,
      "The symptoms affect sleep, mobility, work, study, feeding, sex, bladder or bowel function, or emotional wellbeing.",
    ],
    emergencySigns: [urgent],
    sources: sourcePair(category),
    clinicalReviewer: null,
    lastReviewed: "8 August 2026",
    reviewed: "8 August 2026",
    version: 1,
  };
}

const replacedOrOverlappingDrafts = new Set([
  "heavy-periods-detailed", "cycle-tracking", "period-pain-at-school", "period-bloating", "period-fatigue",
  "pelvic-inflammatory-disease-treatment", "fertile-window", "preconception-health", "pregnancy-test-timing",
  "pregnancy-due-date", "antenatal-appointments", "breastfeeding-positioning", "postnatal-check",
  "return-to-exercise-postpartum", "breast-awareness", "cervical-screening-results", "sexual-health-check",
  "pelvic-health-physiotherapy",
]);

export const additionalConditions = articleSpecs
  .filter(([id]) => !replacedOrOverlappingDrafts.has(id))
  .map(createArticle);
